WITH flattened_attrs AS (SELECT id, effective_from, currency, tier_limits, tier_prices, discounts, SLICE(tier_limits, 1, 2) AS first_two_limits, ARRAY_MIN(tier_prices) AS lowest_price FROM price_tiers WHERE currency IN ('EUR', 'THB', 'USD')) SELECT id, effective_from, currency, lowest_price, ROW_NUMBER() OVER w_recent AS event_seq, LAG(lowest_price, 1) OVER w_recent AS prev_lowest_price, SUM(lowest_price) OVER (PARTITION BY MONTH(effective_from), currency) AS effective_from_month_sum_lowest_price, FIRST_VALUE(lowest_price, TRUE) OVER (PARTITION BY MONTH(effective_from), currency ORDER BY effective_from, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_lowest_price FROM flattened_attrs WINDOW w_recent AS (PARTITION BY currency ORDER BY lowest_price, id);
